(x, y, t) => {
  const PI = Math.PI, nx = x / 480, ny = y / 240;
  const seeds = [];
  for (let i = 0; i < 6; i++) {
    const a = i * 2.399 + t * (0.18 + i * 0.04);
    const r = 0.28 + 0.12 * Math.sin(t * 0.25 + i * 1.1);
    seeds.push([0.5 + r * Math.cos(a), 0.5 + r * Math.sin(a) * 0.55, (5.5 + i * 1.8) * PI, t * (1.4 - i * 0.12) + i * 0.9]);
  }
  const waves = seeds.map(s => {
    const dx = nx - s[0], dy = ny - s[1];
    return Math.sin(Math.sqrt(dx * dx + dy * dy) * s[2] + s[3]);
  });
  let field = 0, cross = 0, n = waves.length;
  for (let i = 0; i < n; i++) {
    field += waves[i];
    for (let j = i + 1; j < n; j++) cross += waves[i] * waves[j];
  }
  field /= n; cross /= (n * (n - 1) / 2);
  let react = Math.tanh((field - cross * 0.85) * 3.8);
  let detail = Math.tanh(Math.sin(field * PI * 3.2) * Math.cos(cross * PI * 2.1 + t * 0.35) * 2.8);
  let p = react * 0.72 + detail * 0.28;
  let base = 0.5 + 0.5 * p, warm = 0.5 + 0.5 * Math.sin(field * PI * 1.6 + t * 0.18);
  let cool = 0.5 + 0.5 * Math.cos(cross * PI * 1.3 - t * 0.12);
  let edge = Math.abs(react) < 0.35 ? 1.0 - Math.abs(react) / 0.35 : 0;
  let r = base * 0.92 + warm * 0.52 + cool * 0.12 + edge * 0.65;
  let g = base * 0.48 + warm * 0.28 + cool * 0.78 + edge * 0.52;
  return [0, 0, 0];
}
